"use client"

import animation from "react-useanimations/lib/thumbUp"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Thumb up" from https://useanimations.com (MIT): https://useanimations.com/icons/thumb-up
export function AnimatedThumbUp(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="click-toggle"
      {...props}
    />
  )
}
